/**
 * Dragon Heir art assets — the skin carries no static files, so every
 * artwork ships as a data URL (SVG data URIs for the seal favicons and the
 * placeholders, WebP base64 for the generated bitmap artworks).
 *
 * Two themed artworks swap by the base theme system (`data-ds-dark-theme`):
 *   LIGHT_ART — 不屈龙魂 (Unyielding Dragon Soul): an ink dragon painting.
 *   DARK_ART  — 万里长城 (The Great Wall): ink-blue mountains at dusk.
 *               Both ship as WebP base64 data URLs, spliced in by the
 *               embed script — search for `LIGHT_ART = "` to swap one.
 *
 * And two seal favicons (48x48), the 龙 character carved in a seal:
 *   LIGHT_ICON — 朱砂 seal (vermilion block, cream glyph)
 *   DARK_ICON  — 鎏金 seal (gold block, dark-red glyph)
 */

const svgUri = (svg: string): string => `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`

/** Light theme artwork — 不屈龙魂 (Unyielding Dragon Soul): the real
 *  gpt-image-2 ink-dragon painting (WebP -> base64 data URL). */
export const LIGHT_ART = 'data:image/webp;base64,'

/** Dark theme artwork — 万里长城 (The Great Wall): the real gpt-image-2
 *  painting (WebP -> base64 data URL). */
export const DARK_ART = 'data:image/webp;base64,'

/** 朱砂 seal favicon — vermilion block, cream 龙 glyph (light theme). */
export const LIGHT_ICON = svgUri(
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48">' +
  '<rect x="3" y="3" width="42" height="42" rx="9" fill="#c3272b"/>' +
  '<rect x="6" y="6" width="36" height="36" rx="7" fill="none" stroke="#fdf8ee" stroke-opacity="0.55" stroke-width="1.5"/>' +
  '<text x="24" y="34" font-size="28" text-anchor="middle" font-family="Kaiti, KaiTi, STKaiti, serif" fill="#fdf8ee">龙</text>' +
  '</svg>',
)

/** 鎏金 seal favicon — gold block, dark-red 龙 glyph (dark theme). */
export const DARK_ICON = svgUri(
  '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 48 48">' +
  '<rect x="3" y="3" width="42" height="42" rx="9" fill="#c8a24a"/>' +
  '<rect x="6" y="6" width="36" height="36" rx="7" fill="none" stroke="#3a0d0b" stroke-opacity="0.5" stroke-width="1.5"/>' +
  '<text x="24" y="34" font-size="28" text-anchor="middle" font-family="Kaiti, KaiTi, STKaiti, serif" fill="#3a0d0b">龙</text>' +
  '</svg>',
)
